  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C31"],
      "claim": "Ondansetron showed ~85% absolute oral bioavailability in humans, a direct high-transfer measurement supporting F ≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C41"],
      "claim": "Indomethacin had ~97% absolute oral bioavailability in humans, directly supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Telmisartan, which shares a benzimidazole and carboxylic acid motif with the query, showed 43% absolute oral bioavailability in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Imidafenacin had 57.8% absolute oral bioavailability in healthy subjects, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C48"],
      "claim": "Encorafenib showed 85% oral bioavailability in humans, another high-transfer example of F ≥20%.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "High-transfer human absolute bioavailability data across multiple drugs consistently show F ≥20% (43–97%), overriding the uncertain physicochemical prior; confidence is tempered by the query's unique amidine-zwitterion motif not being directly represented.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the query or a close analogue containing the strongly basic amidine plus carboxylate zwitterion.",
    "The supplied high-F analogues lack the query's permanently charged amidine and carboxylic acid pair, so transferability of their absorption mechanisms is uncertain.",
    "No evidence addresses possible active transport, efflux, or first-pass metabolism specific to the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

